<?php
require_once(__DIR__.'/../../config.php');require_once(__DIR__.'/classes/local/academy_workspace_view.php');
require_once(__DIR__.'/classes/local/academy_discussion_view.php');
use local_learning_workspace\local\academy_blended as b;use local_learning_workspace\local\academy_workspace_view as v;use local_learning_workspace\local\academy_workspace as w;
require_login();$id=required_param('id',PARAM_INT);try{$s=b::session($id);$group=b::require_group((int)$s->groupid);}catch(DomainException|dml_missing_record_exception $e){b::denied();return;}$staff=b::trainer()||w::manager();$error='';$messagebody=optional_param('body','',PARAM_TEXT);
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 require_sesskey();$action=required_param('action',PARAM_ALPHA);
 try{w::consume_form($action);
 switch($action){
 case 'question':b::post($id,optional_param('parentid',0,PARAM_INT),$messagebody);break;
 case 'moderate':b::moderate(required_param('postid',PARAM_INT),required_param('moderation',PARAM_ALPHA));break;
 case 'attendance':b::attendance($id,required_param('userid',PARAM_INT),required_param('attendstatus',PARAM_ALPHA),optional_param('note','',PARAM_TEXT));break;
 case 'watched':b::attendance($id,(int)$USER->id,'unknown','',true);break;
 default:throw new DomainException('Неизвестное действие.');}
 redirect(b::url('session',['id'=>$id,'saved'=>1]));
 }catch(DomainException $e){$error=$e->getMessage();}
}
v::start('help','session',$error,optional_param('saved',0,PARAM_BOOL)?'Изменения сохранены.':'',$s->title);
echo '<p><a href="academy_sessions.php">← Занятия и группа</a></p><p class="aw-meta">'.v::e($group->name).' · День '.substr($s->lessonid,1).'</p>';
?>
<section class="aw-panel"><h2>Встреча с тренером</h2><p><?=\local_learning_workspace\local\academy_timezone::render((int)$s->startsat)?> · <?=(int)$s->duration?> минут</p><p class="aw-meta"><?=v::e(w::text('timezone_label',\local_learning_workspace\local\academy_timezone::label((int)$s->startsat)))?> · <a href="academy_profile.php"><?=v::e(w::text('timezone_change'))?></a></p>
<?php if($s->status==='cancelled'):?><p role="status">Занятие отменено. Ссылку входа не используйте; тренер сообщит о новой встрече.</p><?php elseif($s->meeturl&&$s->status==='planned'):?><p><a class="lw-primary" href="<?=v::e($s->meeturl)?>" target="_blank" rel="noopener noreferrer">Подключиться в Google Meet ↗</a></p><?php elseif($s->status==='finished'):?><p>Занятие завершено. Ниже находятся конспект, запись и вопросы.</p><?php else:?><p>Ссылка на встречу появится здесь после подготовки тренером.</p><?php endif;?>
<div class="ab-inline"><a href="<?=v::e(b::url('calendar',['id'=>$id])->out(false))?>">Добавить в календарь</a><a href="<?=$s->lessonid==='L1'?'lesson_one.php':'academy_day.php?lesson='.v::e($s->lessonid)?>">Материалы дня →</a><?php if($staff):?><a href="academy_teaching.php?edit=<?=$id?>">Изменить занятие</a><?php endif;?></div>
<?php if($s->agenda!==''):?><h3>Что разберём</h3><p><?=nl2br(v::e($s->agenda))?></p><?php endif;?>
<p class="aw-meta">Встреча может записываться для участников этой группы. Тренер предупреждает о записи до её начала. Если вы не готовы попадать в запись, заранее напишите тренеру.</p></section>
<?php if($s->summary!==''&&($s->published||$staff||$s->status==='finished')):?><section class="aw-panel"><h2>Итоги занятия</h2><p><?=nl2br(v::e($s->summary))?></p></section><?php endif;?>
<?php if(($s->published||$staff)&&($s->recordname!==''||$s->recordurl!=='')):?><section class="aw-panel" id="recording"><h2>Запись занятия <?=$s->published?'':'· черновик, виден тренеру'?></h2>
<?php if($s->recordname!==''):?><video class="ab-video" controls playsinline preload="metadata" aria-label="Запись занятия <?=v::e($s->title)?>" src="<?=v::e(b::url('recording',['id'=>$id])->out(false))?>"><?php if($s->captionname!==''):?><track kind="captions" srclang="ru" label="Русские" src="<?=v::e(b::url('recording',['id'=>$id,'caption'=>1])->out(false))?>"><?php endif;?>Ваш браузер не поддерживает встроенное видео.</video><label for="record-speed">Скорость воспроизведения</label><select id="record-speed" data-video-speed><?php foreach([0.75,1,1.25,1.5,2] as $rate):?><option value="<?=$rate?>" <?=$rate==1?'selected':''?>><?=$rate?>×</option><?php endforeach;?></select>
<?php elseif($s->recordurl!==''):?><p>Запись хранится в Google Drive. Доступ к файлу отдельно выдаёт организатор; платформа не меняет настройки доступа Google.</p><p><a href="<?=v::e($s->recordurl)?>" target="_blank" rel="noopener noreferrer">Открыть запись в Google Drive ↗</a></p><details class="lw-details"><summary>Посмотреть внутри платформы</summary><iframe class="ab-drive" title="Запись занятия в Google Drive" src="<?=v::e(preg_replace('~/view(?:\?.*)?$~','/preview',$s->recordurl))?>" allow="fullscreen" referrerpolicy="no-referrer" loading="lazy"></iframe></details><?php endif;?>
<?php if(!$staff&&$s->published):$ownatt=$DB->get_record('local_lworkspace_attend',['sessionid'=>$id,'userid'=>$USER->id]);if(empty($ownatt->watched)):?><form method="post"><?=v::fields('watched')?><button class="aw-secondary">Я посмотрел запись</button><p class="aw-meta">Это отметка для тренера, не оценка и не замена контрольной работе.</p></form><?php else:?><p role="status">Вы отметили просмотр записи.</p><?php endif;endif;?></section><?php elseif($s->status==='finished'):?><section class="aw-panel"><h2>Запись занятия</h2><p>Тренер ещё не опубликовал запись. Материалы и вопросы доступны независимо от неё.</p></section><?php endif;?>
<?php if($staff):?><section class="aw-panel"><h2>Учащиеся и обратная связь</h2><p>Посещение отмечается отдельно от оценки. Контрольные ответы проверяйте в кабинете работ.</p><?php foreach(b::members((int)$s->groupid) as $member):if(!\local_learning_workspace\local\academy_access::is_candidate((int)$member->id)){continue;}$att=$DB->get_record('local_lworkspace_attend',['sessionid'=>$id,'userid'=>$member->id]);?><details class="lw-details"><summary><?=v::e(fullname($member))?> · <?=v::e(['unknown'=>'Без отметки','attended'=>'Присутствовал','missed'=>'Отсутствовал','catchup'=>'Нужен разбор'][$att->status??'unknown'])?> <?=!empty($att->watched)?'· запись просмотрена':''?></summary><p><a href="academy_onboarding.php?user=<?=(int)$member->id?>">Учебная анкета</a> · <a href="academy_candidate.php?userid=<?=(int)$member->id?>">Работы и замечания</a></p><form method="post"><?=v::fields('attendance')?><input type="hidden" name="userid" value="<?=(int)$member->id?>"><label for="att-<?=(int)$member->id?>">Посещение</label><select id="att-<?=(int)$member->id?>" name="attendstatus"><?php foreach(['unknown'=>'Без отметки','attended'=>'Присутствовал','missed'=>'Отсутствовал','catchup'=>'Нужен разбор'] as $value=>$label):?><option value="<?=$value?>" <?=($att->status??'unknown')===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select><label for="note-<?=(int)$member->id?>">Заметка тренера — видна только тренерам группы</label><textarea id="note-<?=(int)$member->id?>" name="note" maxlength="600"><?=v::e($att->note??'')?></textarea><button>Сохранить отметку</button></form></details><?php endforeach;?></section><?php endif;?>
<section class="aw-panel" id="discussion"><h2>Вопросы по занятию</h2><p id="discussion-help">Вопросы и ответы видят участники этой группы и её тренеры. Личные оценки и данные клиентов здесь не публикуйте.</p>
<form method="post" class="ab-question-form"><?=v::fields('question')?><label for="session-question">Задать вопрос</label><textarea id="session-question" name="body" maxlength="4000" rows="4" aria-describedby="discussion-help" required><?=v::e($error&&!optional_param('parentid',0,PARAM_INT)?$messagebody:'')?></textarea><div class="aw-form-actions"><button>Отправить вопрос</button></div></form>
<?php $page=max(0,optional_param('page',0,PARAM_INT));$where='sessionid=:sid AND parentid=0'.($staff?'':' AND active=1');$total=$DB->count_records_select('local_lworkspace_discuss',$where,['sid'=>$id]);$page=min($page,max(0,(int)ceil($total/20)-1));$threads=$DB->get_records_select('local_lworkspace_discuss',$where,['sid'=>$id],'pinned DESC,id DESC','*',$page*20,20);if(!$threads):?><p>Вопросов пока нет. Можно начать обсуждение.</p><?php endif;
if(optional_param('action','',PARAM_ALPHA)==='question'){
 echo \local_learning_workspace\local\academy_discussion_view::reply_recovery($error,optional_param('parentid',0,PARAM_INT),$messagebody,$threads);
}
$render=static function($post)use($staff,$USER,$id){global $DB;$author=$DB->get_record('user',['id'=>$post->userid],'id,firstname,lastname');echo '<div class="ab-post"><p class="aw-meta">'.v::e($author?fullname($author):'Участник').' · '.v::e(userdate($post->timecreated,'%d.%m · %H:%M')).($post->pinned?' · Закреплено':'').(!$post->active?' · Скрыто':'').'</p><p>'.nl2br(v::e($post->body)).'</p>';if($staff||(int)$post->userid===(int)$USER->id){echo '<form method="post" class="ab-inline">'.v::fields('moderate').'<input type="hidden" name="postid" value="'.(int)$post->id.'">';if($staff&&!$post->parentid){echo '<button class="aw-secondary" name="moderation" value="pin">'.($post->pinned?'Открепить':'Закрепить').'</button>';}echo '<button class="aw-secondary" name="moderation" value="'.($post->active?'archive':'restore').'">'.($post->active?'Скрыть':'Вернуть').'</button></form>';}echo '</div>';};
foreach($threads as $thread):?><article class="ab-thread" id="question-<?=(int)$thread->id?>"><?php $render($thread);$replywhere='sessionid=:s AND parentid=:p'.($staff?'':' AND active=1');$replyparams=['s'=>$id,'p'=>$thread->id];$replycount=$DB->count_records_select('local_lworkspace_discuss',$replywhere,$replyparams);$replypage=min(max(0,optional_param('replypage_'.$thread->id,0,PARAM_INT)),max(0,(int)ceil($replycount/10)-1));$replies=$DB->get_records_select('local_lworkspace_discuss',$replywhere,$replyparams,'id ASC','*',$replypage*10,10);foreach($replies as $reply){$render($reply);}if($replycount>10):?><nav class="ab-inline" aria-label="Страницы ответов на вопрос"><?php if($replypage):?><a href="?id=<?=$id?>&amp;page=<?=$page?>&amp;replypage_<?=(int)$thread->id?>=<?=$replypage-1?>#question-<?=(int)$thread->id?>">← Ранее</a><?php endif;?>Ответы <?=$replypage*10+1?>–<?=min(($replypage+1)*10,$replycount)?> из <?=$replycount?><?php if(($replypage+1)*10<$replycount):?><a href="?id=<?=$id?>&amp;page=<?=$page?>&amp;replypage_<?=(int)$thread->id?>=<?=$replypage+1?>#question-<?=(int)$thread->id?>">Далее →</a><?php endif;?></nav><?php endif;if($thread->active):
$replyerror=$error!==''&&optional_param('parentid',0,PARAM_INT)==$thread->id;
?><details class="lw-details" <?=$replyerror?'open':''?>><summary>Ответить на вопрос</summary>
<form method="post" class="ab-question-form"><?=v::fields('question')?><input type="hidden" name="parentid" value="<?=(int)$thread->id?>"><label for="reply-<?=(int)$thread->id?>">Ваш ответ</label><textarea id="reply-<?=(int)$thread->id?>" name="body" maxlength="4000" rows="4" aria-describedby="discussion-help" required><?=v::e($replyerror?$messagebody:'')?></textarea><div class="aw-form-actions"><button>Отправить ответ</button></div></form>
</details><?php endif;?></article><?php endforeach;?>
<?php if($total>20):?><nav class="ab-inline" aria-label="Страницы вопросов"><?php if($page):?><a href="?id=<?=$id?>&amp;page=<?=$page-1?>#discussion">← Предыдущие</a><?php endif;?>Страница <?=$page+1?> из <?=(int)ceil($total/20)?><?php if(($page+1)*20<$total):?><a href="?id=<?=$id?>&amp;page=<?=$page+1?>#discussion">Следующие →</a><?php endif;?></nav><?php endif;?></section>
<?php v::end();
